/** @param {NS} ns */
export async function main(ns) {
  // List all properties of ns
  try {
    const keys = Object.getOwnPropertyNames(ns);
    ns.tprint('NS KEYS: ' + JSON.stringify(keys));
  } catch(e) { ns.tprint('keys error: ' + e); }

  // Try prototype methods
  try {
    const proto = Object.getOwnPropertyNames(Object.getPrototypeOf(ns));
    ns.tprint('NS PROTO: ' + JSON.stringify(proto));
  } catch(e) { ns.tprint('proto error: ' + e); }

  // Try common getters safely
  const probes = [
    () => { const r = ns.getPlayer?.(); ns.tprint('getPlayer: ' + JSON.stringify(r)); },
    () => { const r = ns.getServer?.('home'); ns.tprint('getServer home: ' + JSON.stringify(r)); },
    () => { const r = ns.scan?.(); ns.tprint('scan: ' + JSON.stringify(r)); },
    () => { const r = ns.ls?.('home'); ns.tprint('ls home: ' + JSON.stringify(r)); },
    () => { const r = ns.getHostname?.(); ns.tprint('hostname: ' + r); },
    () => { const r = ns.getServerMoneyAvailable?.('home'); ns.tprint('money home: ' + r); },
    () => { const r = ns.getHackingLevel?.(); ns.tprint('hackLevel: ' + r); },
  ];
  for (const p of probes) {
    try { p(); } catch(e) { ns.tprint('probe error: ' + e); }
  }
}

